/* Method 1: Google Fonts (in HTML head) */
/* <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"> */

body { font-family: 'Inter', sans-serif; }

/* Method 2: @font-face (self-hosted) */
@font-face {
  font-family: 'MyFont';
  src: url('/fonts/myfont.woff2') format('woff2'),
       url('/fonts/myfont.woff') format('woff');
  font-weight: 400;
  font-style: normal;
  font-display: swap; /* show fallback font while loading */
}

:root {
  --text-xs:   0.75rem;  /* 12px */
  --text-sm:   0.875rem; /* 14px */
  --text-base: 1rem;     /* 16px */
  --text-lg:   1.125rem; /* 18px */
  --text-xl:   1.25rem;  /* 20px */
  --text-2xl:  1.5rem;   /* 24px */
  --text-3xl:  1.875rem; /* 30px */
  --text-4xl:  2.25rem;  /* 36px */
}

body {
  font-size: var(--text-base);
  line-height: 1.6;          /* unitless — scales with font size */
  letter-spacing: -0.01em;
}

h1 { font-size: var(--text-4xl); line-height: 1.2; font-weight: 800; }
h2 { font-size: var(--text-3xl); line-height: 1.3; font-weight: 700; }

/* Hex */
color: #6366f1;          /* 3 pairs: RR,GG,BB */
color: #6366f180;        /* with alpha (80 = 50%) */

/* RGB */
color: rgb(99, 102, 241);
color: rgba(99, 102, 241, 0.5);

/* HSL — most intuitive for designers */
color: hsl(239, 84%, 67%);
/* H: 0-360°, S: saturation %, L: lightness % */
color: hsl(239 84% 67% / 0.5); /* modern slash syntax with alpha */

/* oklch — the future (perceptually uniform) */
color: oklch(65% 0.23 264);

/* Linear gradient */
.hero {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

/* Multi-stop gradient */
.rainbow {
  background: linear-gradient(
    to right,
    #ff0000, #ff8800, #ffff00,
    #00ff00, #0000ff, #8800ff
  );
}

/* Radial gradient */
.spotlight {
  background: radial-gradient(circle at center, #fff 0%, #000 100%);
}

/* Conic gradient (pie charts, spinners) */
.pie {
  background: conic-gradient(#6366f1 0% 40%, #e2e8f0 40% 100%);
  border-radius: 50%;
}

/* Gradient text */
.gradient-text {
  background: linear-gradient(135deg, #667eea, #764ba2);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero {
  background-image: url('/hero.jpg');
  background-size: cover;       /* fill container, may crop */
  background-position: center;  /* anchor point */
  background-repeat: no-repeat;
  background-attachment: fixed; /* parallax effect */
}

/* Multiple background layers */
.fancy {
  background:
    linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)),
    url('/hero.jpg') center/cover no-repeat;
}

/* object-fit for img elements (like background-size for img) */
img.cover {
  width: 100%;
  height: 300px;
  object-fit: cover;
  object-position: top;
}

/* Text decoration */
a { text-decoration: none; }
a:hover { text-decoration: underline 2px solid currentColor; }

/* Text transform */
.btn { text-transform: uppercase; letter-spacing: 0.1em; }
.name { text-transform: capitalize; }

/* Text shadow */
.glow { text-shadow: 0 0 10px #6366f1, 0 0 30px rgba(99,102,241,0.4); }

/* Fluid typography with clamp() */
h1 {
  font-size: clamp(1.5rem, 4vw, 3rem);
  /* min: 1.5rem, preferred: 4vw, max: 3rem */
}

/* Truncate overflowing text */
.card-title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Multiline clamp */
.summary {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
